/**
 * GraphQL SDK Client — PIX-4066
 *
 * Type-safe GraphQL client generated from the Pixelated Empathy GraphQL schema.
 * Uses `graphql-request` for isomorphic (Node + browser) HTTP transport.
 *
 * All query/mutation/subscription types are generated by @graphql-codegen from
 * `src/lib/graphql/schema.graphql` and operation documents in
 * `src/lib/graphql/operations/`.
 *
 * Usage:
 * ```typescript
 * import { createGraphqlClient } from "@/lib/graphql/client";
 *
 * const client = createGraphqlClient({
 *   endpoint: "http://localhost:5173/api/graphql",
 *   apiKey: "pk_...",
 * });
 *
 * const { health } = await client.health();
 * const session = await client.getSession({ id: "abc123" });
 * ```
 */

